import{_ as s,a0 as r,w as a,s as d,I as n,x as e,a1 as p,A as l,ao as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"如何在CentOS 7.x中安装OpenERP（Odoo） | LCTT x X-CMD","titleTemplate":false,"description":"如何在CentOS 7.x中安装OpenERP（Odoo） | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在CentOS 7.x中安装OpenERP（Odoo） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在CentOS 7.x中安装OpenERP（Odoo） | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150506 How to Setup OpenERP (Odoo) on CentOS 7.x","title":"如何在CentOS 7.x中安装OpenERP（Odoo）","tag":"201506","desc":""},"relativePath":"201506/20150506 How to Setup OpenERP (Odoo) on CentOS 7.x.md","filePath":"[post].md"}'),g={name:"201506/20150506 How to Setup OpenERP (Odoo) on CentOS 7.x.md"};function O(m,o,u,P,c,x){const t=r("Link");return a(),d("div",null,[o[15]||(o[15]=n("h1",{id:"如何在centos-7-x中安装openerp-odoo",tabindex:"-1"},[e("如何在CentOS 7.x中安装OpenERP（Odoo） "),n("a",{class:"header-anchor",href:"#如何在centos-7-x中安装openerp-odoo","aria-label":"Permalink to “如何在CentOS 7.x中安装OpenERP（Odoo）”"},"​")],-1)),o[16]||(o[16]=n("p",null,"各位好，这篇教程关于的是如何在CentOS 7中安装Odoo（就是我们所知的OpenERP）。你是不是在考虑为你的业务安装一个不错的ERP（企业资源规划）软件？那么OpenERP就是你寻找的最好的程序，因为它是一款为你的商务提供杰出特性的自由开源软件。",-1)),n("p",null,[p(t,{href:"https://www.odoo.com/"},{default:l(()=>[...o[0]||(o[0]=[e("OpenERP",-1)])]),_:1}),o[1]||(o[1]=e("是一款自由开源的传统的OpenERP（企业资源规划），它包含了开源CRM、网站构建、电子商务、项目管理、计费账务、POS、人力资源、市场、生产、采购管理以及其它模块用于提高效率及销售。Odoo中的应用可以作为独立程序使用，它们也可以无缝集成到一起，因此你可以在安装几个程序来得到一个全功能的开源ERP。",-1))]),o[17]||(o[17]=i(`<p>因此，下面是在你的CentOS上安装OpenERP的步骤。</p><h3 id="_1-安装-postgresql" tabindex="-1">1. 安装 PostgreSQL <a class="header-anchor" href="#_1-安装-postgresql" aria-label="Permalink to “1. 安装 PostgreSQL”">​</a></h3><p>首先，首先我们需要更新CentOS 7的软件包来确保是最新的包，补丁和安全更新。要更新我们的系统，我们要在shell下运行下面的命令。</p><pre><code># yum clean all
# yum update
</code></pre><p>现在我们要安装PostgreSQL，因为OpenERP使用PostgreSQL作为它的数据库。要安装它，我们需要运行下面的命令。</p><pre><code># yum install postgresql postgresql-server postgresql-libs
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/installing-postgresql.png" alt="Installing postgresql"></p><p>安装完成后，我们需要用下面的命令初始化数据库。</p><pre><code># postgresql-setup initdb
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/intializating-postgresql.png" alt="Intializating postgresql"></p><p>我们接着设置PostgreSQL来使它每次开机启动。</p><pre><code># systemctl enable postgresql
# systemctl start postgresql
</code></pre><p>因为我们还没有为用户“postgresql”设置密码，我们现在设置。</p><pre><code># su - postgres
$ psql
postgres=# \\password postgres
postgres=# \\q
# exit
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/setting-password-postgres.png" alt="setting password postgres"></p><h3 id="_2-设置odoo仓库" tabindex="-1">2. 设置Odoo仓库 <a class="header-anchor" href="#_2-设置odoo仓库" aria-label="Permalink to “2. 设置Odoo仓库”">​</a></h3><p>在初始化数据库初始化完成后，我们要添加 EPEL（企业版Linux的额外包）到我们的CentOS中。Odoo（或者OpenERP）依赖的Python运行时环境以及其他包没有包含在标准仓库中。这样我们要为企业版Linux添加额外的包仓库支持来解决Odoo所需要的依赖。要安装完成，我们需要运行下面的命令。</p><pre><code># yum install epel-release
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/installing-epel-release.png" alt="Installing EPEL Release"></p><p>现在，安装EPEL后，我们现在使用yum-config-manager添加Odoo（OpenERP）的仓库。</p><pre><code># yum install yum-utils

# yum-config-manager --add-repo=https://nightly.odoo.com/8.0/nightly/rpm/odoo.repo
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/added-odoo-repo.png" alt="Adding OpenERP (Odoo) Repo"></p><h3 id="_3-安装odoo-8-openerp" tabindex="-1">3. 安装Odoo 8 (OpenERP) <a class="header-anchor" href="#_3-安装odoo-8-openerp" aria-label="Permalink to “3. 安装Odoo 8 (OpenERP)”">​</a></h3><p>在CentOS 7中添加Odoo 8（OpenERP）的仓库后。我们使用下面的命令来安装Odoo 8(OpenERP)。</p><pre><code># yum install -y odoo
</code></pre><p>上面的命令会安装odoo以及必须的依赖的包。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/installing-odoo.png" alt="Installing odoo or OpenERP"></p><p>现在我们使用下面的命令在每次启动后启动Odoo服务。</p><pre><code># systemctl enable odoo
# systemctl start odoo
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/starting-odoo.png" alt="Starting Odoo"></p><h3 id="_4-打开防火墙" tabindex="-1">4. 打开防火墙 <a class="header-anchor" href="#_4-打开防火墙" aria-label="Permalink to “4. 打开防火墙”">​</a></h3><p>因为Odoo使用8069端口，我们需要在防火墙中允许远程访问。我们使用下面的命令来在防火墙中允许8069端口访问。</p><pre><code># firewall-cmd --zone=public --add-port=8069/tcp --permanent
# firewall-cmd --reload
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/allowing-firewall-port.png" alt="Allowing firewall Port"></p><p><strong>注意：默认情况下只有本地才允许连接数据库。如果我们要允许PostgreSQL的远程访问，我们需要在pg_hba.conf添加下面图片中一行</strong></p><pre><code># nano /var/lib/pgsql/data/pg_hba.conf
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/allowing-remote-access-pgsql.png" alt="Allowing Remote Access pgsql"></p><h3 id="_5-web接口" tabindex="-1">5. Web接口 <a class="header-anchor" href="#_5-web接口" aria-label="Permalink to “5. Web接口”">​</a></h3><p>我们已经在CentOS 7中安装了最新的Odoo 8（OpenERP），我们可以在浏览器中输入<code>http://ip-address:8069</code>来访问Odoo。 接着，我们要做的第一件事就是创建一个新的数据库和新的密码。注意，主密码默认是‘admin’。接着，我们可以在面板中输入用户名和密码。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/odoo-panel.png" alt="Odoo Panel"></p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>Odoo 8（OpenERP）是世界上最好的开源ERP程序。OpenERP是由许多模块组成的针对商务和公司的完整ERP程序，我们已经把它安装好了。因此，如果你有任何问题、建议、反馈请在下面的评论栏写下。谢谢你！享受OpenERP（Odoo 8）吧 ：-）</p><hr>`,43)),n("p",null,[o[3]||(o[3]=e("via: ",-1)),p(t,{href:"http://linoxide.com/linux-how-to/setup-openerp-odoo-centos-7/"},{default:l(()=>[...o[2]||(o[2]=[e("http://linoxide.com/linux-how-to/setup-openerp-odoo-centos-7/",-1)])]),_:1})]),n("p",null,[o[7]||(o[7]=e("作者：",-1)),p(t,{href:"http://linoxide.com/author/arunp/"},{default:l(()=>[...o[4]||(o[4]=[e("Arun Pyasi",-1)])]),_:1}),o[8]||(o[8]=e(" 译者：",-1)),p(t,{href:"https://github.com/geekpi"},{default:l(()=>[...o[5]||(o[5]=[e("geekpi",-1)])]),_:1}),o[9]||(o[9]=e(" 校对：",-1)),p(t,{href:"https://github.com/wxy"},{default:l(()=>[...o[6]||(o[6]=[e("wxy",-1)])]),_:1})]),n("p",null,[o[12]||(o[12]=e("本文由 ",-1)),p(t,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...o[10]||(o[10]=[e("LCTT",-1)])]),_:1}),o[13]||(o[13]=e(" 原创翻译，",-1)),p(t,{href:"https://linux.cn/"},{default:l(()=>[...o[11]||(o[11]=[e("Linux中国",-1)])]),_:1}),o[14]||(o[14]=e(" 荣誉推出",-1))])])}const f=s(g,[["render",O]]);export{b as __pageData,f as default};
